prts.feedbackvariables:
xs:radcan(ans1);
ys:radcan(ans2);

lx:limit(xs,t,0,plus);
ly:limit(ys,t,0,plus);

approach:numberp(lx) and numberp(ly) and is(equal(lx,0)) and is(equal(ly,0));

pzero:if freeof(t,xs) and freeof(t,ys)
      then is(equal(xs,0)) and is(equal(ys,0))
      else false;

denpath:radcan(subst([x=xs,y=ys],den));

denbad:if freeof(t,denpath)
       then is(equal(denpath,0))
       else false;

pathok:approach and not pzero and not denbad;

xs:radcan(ans1);
ys:radcan(ans2);

lx:limit(xs,t,0,plus);
ly:limit(ys,t,0,plus);

approach:numberp(lx) and numberp(ly) and is(equal(lx,0)) and is(equal(ly,0));

pzero:if freeof(t,xs) and freeof(t,ys)
      then is(equal(xs,0)) and is(equal(ys,0))
      else false;

denpath:radcan(subst([x=xs,y=ys],den));

denbad:if freeof(t,denpath)
       then is(equal(denpath,0))
       else false;

pathok:approach and not pzero and not denbad;

pathexpr:if denbad then 0 else radcan(subst([x=xs,y=ys],f));
calc:if denbad then und else limit(pathexpr,t,0,plus);

badcalc:member(calc,[und,ind]);

samevalue:if badcalc then false
          elseif member(calc,[inf,minf]) then is(equal(calc,ans3))
          else is(equal(radcan(calc-ans3),0));

limitok:pathok and samevalue;

